-- P3: immutable-within-lifecycle, transactionally derived snapshot change evidence.
-- It is generated by the server from indexed path/content-hash manifests,
-- never accepted as authoritative from an unverified Git client sidecar.
BEGIN;
CREATE TABLE code_snapshot_change_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    repository_id uuid NOT NULL REFERENCES code_repositories(id) ON DELETE CASCADE,
    snapshot_id uuid NOT NULL REFERENCES code_repository_snapshots(id) ON DELETE CASCADE,
    change_kind text NOT NULL CHECK (change_kind IN ('add','modify','delete','rename','copy')),
    path text NOT NULL CHECK (length(path) > 0),
    previous_path text,
    evidence_class text NOT NULL CHECK (
        evidence_class IN ('exact_path','snapshot_manifest','unambiguous_content')
    ),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (snapshot_id,path),
    CHECK ((change_kind IN ('rename','copy')) = (previous_path IS NOT NULL)),
    CHECK (previous_path IS NULL OR (previous_path <> path AND length(previous_path) > 0))
);
CREATE INDEX code_snapshot_changes_tenant_repo_idx
    ON code_snapshot_change_events(tenant_id,repository_id,snapshot_id);

ALTER TABLE code_snapshot_change_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE code_snapshot_change_events FORCE ROW LEVEL SECURITY;
CREATE POLICY code_snapshot_change_events_tenant_read
    ON code_snapshot_change_events FOR SELECT
    USING (tenant_id = NULLIF(current_setting('scos.tenant_id',true),'')::uuid);
CREATE POLICY code_snapshot_change_events_tenant_insert
    ON code_snapshot_change_events FOR INSERT
    WITH CHECK (
        tenant_id = NULLIF(current_setting('scos.tenant_id',true),'')::uuid
        AND EXISTS (
            SELECT 1 FROM code_repository_snapshots s
            WHERE s.id = snapshot_id
              AND s.repository_id = code_snapshot_change_events.repository_id
              AND s.tenant_id = code_snapshot_change_events.tenant_id
        )
    );
-- Runtime indexing can append, but cannot silently rewrite or delete evidence.
DO $role_grants$
BEGIN
    IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='scos_app') THEN
        GRANT SELECT, INSERT ON code_snapshot_change_events TO scos_app;
        REVOKE UPDATE, DELETE ON code_snapshot_change_events FROM scos_app;
    END IF;
END
$role_grants$;
COMMIT;
